package com.zachaller.terraformer;

import android.app.Activity;
import android.graphics.Insets;
import android.os.Build;
import android.os.Bundle;
import android.view.DisplayCutout;
import android.view.View;
import android.view.WindowInsets;
import android.view.WindowInsetsController;
import android.view.WindowManager;
import android.widget.FrameLayout;

import com.zachaller.terraformer.mobile.EbitenView;
import com.zachaller.terraformer.mobile.Mobile;

import go.Seq;

// MainActivity hosts the Go game, which runs inside an EbitenView generated by
// ebitenmobile. It runs full-screen with the system bars hidden (swipe from an
// edge to bring them back) and tells the game which screen edges the bars and
// any camera cutout can cover, so buttons and text stay clear of them.
public class MainActivity extends Activity {
    private EbitenView view;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        Seq.setContext(getApplicationContext());
        Mobile.setDataDir(getFilesDir().getAbsolutePath());

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
            getWindow().getAttributes().layoutInDisplayCutoutMode =
                    WindowManager.LayoutParams.LAYOUT_IN_DISPLAY_CUTOUT_MODE_SHORT_EDGES;
        }

        view = new EbitenView(this);
        FrameLayout root = new FrameLayout(this);
        root.addView(view);
        root.setOnApplyWindowInsetsListener((v, insets) -> {
            reportSafeArea(insets);
            return v.onApplyWindowInsets(insets);
        });
        setContentView(root);
        hideSystemBars();
    }

    @Override
    public void onWindowFocusChanged(boolean hasFocus) {
        super.onWindowFocusChanged(hasFocus);
        if (hasFocus) {
            hideSystemBars();
        }
    }

    @SuppressWarnings("deprecation")
    private void hideSystemBars() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            getWindow().setDecorFitsSystemWindows(false);
            WindowInsetsController c = getWindow().getInsetsController();
            if (c != null) {
                c.hide(WindowInsets.Type.systemBars());
                c.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);
            }
        } else {
            getWindow().getDecorView().setSystemUiVisibility(
                    View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY
                            | View.SYSTEM_UI_FLAG_FULLSCREEN
                            | View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
                            | View.SYSTEM_UI_FLAG_LAYOUT_STABLE
                            | View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
                            | View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION);
        }
    }

    // reportSafeArea passes the screen edges covered by system bars (even while
    // hidden, since a swipe can bring them back over the game) or a display
    // cutout to the game, in pixels.
    @SuppressWarnings("deprecation")
    private void reportSafeArea(WindowInsets insets) {
        int l, t, r, b;
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.R) {
            Insets i = insets.getInsetsIgnoringVisibility(
                    WindowInsets.Type.systemBars() | WindowInsets.Type.displayCutout());
            l = i.left;
            t = i.top;
            r = i.right;
            b = i.bottom;
        } else {
            l = insets.getStableInsetLeft();
            t = insets.getStableInsetTop();
            r = insets.getStableInsetRight();
            b = insets.getStableInsetBottom();
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.P) {
                DisplayCutout cut = insets.getDisplayCutout();
                if (cut != null) {
                    l = Math.max(l, cut.getSafeInsetLeft());
                    t = Math.max(t, cut.getSafeInsetTop());
                    r = Math.max(r, cut.getSafeInsetRight());
                    b = Math.max(b, cut.getSafeInsetBottom());
                }
            }
        }
        Mobile.setSafeArea(l, t, r, b);
    }

    @Override
    protected void onPause() {
        super.onPause();
        Mobile.save();
        view.suspendGame();
    }

    @Override
    protected void onResume() {
        super.onResume();
        view.resumeGame();
    }
}
